1 | /**
2 |  * models.ts — shared type contracts for sdlc-harness skill agents.
3 |  *
4 |  * These types are the single source of truth consumed by all five agents,
5 |  * the review interface (Task 25), and the telemetry module (Task 26).
6 |  * No GitLab SDK dependency — plain TypeScript interfaces only.
7 |  */
8 | 
9 | // ---------------------------------------------------------------------------
10 | // Project configuration (persisted by onboarding, Task 18)
11 | // ---------------------------------------------------------------------------
12 | 
13 | export interface TransitionRules {
14 |   [fromState: string]: string[];
15 | }
16 | 
17 | export interface ProjectConfig {
18 |   /** GitLab project URL, e.g. "http://localhost:8080/sdlc-harness/weather-dashboard" */
19 |   projectUrl: string;
20 |   /** Work item types in use, e.g. ["Story", "Bug", "Task", "Epic"] */
21 |   workItemTypes: string[];
22 |   /** Ordered workflow states, e.g. ["Open", "In Progress", "In Review", "Done"] */
23 |   workflowStates: string[];
24 |   /** Valid state transitions: { "Open": ["In Progress"], ... } */
25 |   transitionRules: TransitionRules;
26 | }
27 | 
28 | // ---------------------------------------------------------------------------
29 | // Lightweight issue / MR shapes (mirror the MCP server types but without the
30 | // full GitLab schema so agents work without importing the server package)
31 | // ---------------------------------------------------------------------------
32 | 
33 | export interface IssueInput {
34 |   iid: number;
35 |   title: string;
36 |   description: string | null;
37 |   labels: string[];
38 |   state: string;
39 |   assignee: unknown | null;
40 | }
41 | 
42 | export interface MRInput {
43 |   iid: number;
44 |   title: string;
45 |   description: string | null;
46 |   state: string;
47 |   mergedAt?: string | null;
48 | }
49 | 
50 | // ---------------------------------------------------------------------------
51 | // Agent finding types
52 | // ---------------------------------------------------------------------------
53 | 
54 | /** Discriminator tags for each agent. */
55 | export type AgentTag = 'AC' | 'AM' | 'DEP' | 'ST' | 'COV';
56 | 
57 | /**
58 |  * A finding produced by any single-issue agent (AC, AM, ST, COV).
59 |  */
60 | export interface AgentFinding {
61 |   /** Agent that produced this finding. */
62 |   agent: AgentTag;
63 |   /** The issue this finding relates to. */
64 |   issueIid: number;
65 |   /**
66 |    * Short action label for the finding type.
67 |    *  'draft_ac'         — AC agent drafted missing acceptance criteria
68 |    *  'rewrite_desc'     — AM agent proposed a description rewrite
69 |    *  'state_transition' — ST agent proposed a state change
70 |    *  'missing_coverage' — COV agent flagged an issue with no test reference
71 |    */
72 |   action: 'draft_ac' | 'rewrite_desc' | 'state_transition' | 'missing_coverage';
73 |   /** The proposed new value (AC text, rewritten description, or target state). */
74 |   suggestedValue: string;
75 |   /** Human-readable explanation of why this finding was raised. Optional. */
76 |   reason?: string;
77 | }
78 | 
79 | /**
80 |  * A dependency finding produced by the dependency agent (Task 22).
81 |  * Separate type because it spans two issues.
82 |  */
83 | export interface DependencyFinding {
84 |   agent: 'DEP';
85 |   /** Source issue IID (the one that depends on / blocks the other). */
86 |   sourceIid: number;
87 |   /** Target issue IID. */
88 |   targetIid: number;
89 |   /** Proposed link type. */
90 |   suggestedLinkType: 'blocks' | 'relates-to';
91 |   /** Human-readable explanation. */
92 |   reason?: string;
93 |   /** Confidence score in [0,1]. */
94 |   confidence: number;
95 | }
96 | 
97 | /** Union of all finding types surfaced to the review interface. */
98 | export type AnyFinding = AgentFinding | DependencyFinding;
99 | 
100 | // ---------------------------------------------------------------------------
101 | // Review interface types (Task 25)
102 | // ---------------------------------------------------------------------------
103 | 
104 | export type ReviewOutcome = 'accepted' | 'edited' | 'rejected';
105 | 
106 | export interface ReviewOptions {
107 |   /** Provide an edited value to apply instead of the suggestion; null means use as-is. */
108 |   editedValue: string | null;
109 | }
110 | 
111 | export interface ReviewResult {
112 |   /** Whether the GitLab writer adapter was called. */
113 |   gitlabWriteCalled: boolean;
114 |   /** The value actually written (finding's suggestion or the edited value). */
115 |   writtenValue?: string;
116 |   /** Telemetry entry appended for this decision. */
117 |   telemetryEntry: TelemetryEntry;
118 | }
119 | 
120 | // ---------------------------------------------------------------------------
121 | // Telemetry types (Task 26)
122 | // ---------------------------------------------------------------------------
123 | 
124 | export interface TelemetryEntry {
125 |   /** ISO-8601 timestamp of the decision. */
126 |   timestamp: string;
127 |   /** Agent that produced the finding. */
128 |   agent: AgentTag;
129 |   /** Issue IID the finding was about. */
130 |   issueIid: number;
131 |   /** The action / finding type. */
132 |   action: string;
133 |   /** What the user decided. */
134 |   outcome: ReviewOutcome;
135 |   /**
136 |    * Fields that were edited (empty array for 'accepted' / 'rejected').
137 |    * Only 'description' is used in the current agent set.
138 |    */
139 |   editedFields: string[];
140 | }
141 | 
142 | // ---------------------------------------------------------------------------
143 | // Test-coverage linkage types (Task 24 — P1)
144 | // ---------------------------------------------------------------------------
145 | 
146 | export interface CoverageConfig {
147 |   /** Glob patterns for test files to scan, e.g. ["**\/*.test.ts", "tests/**\/*.ts"] */
148 |   testFilePatterns: string[];
149 |   /** Whether the agent is enabled (disabled by default). */
150 |   enabled: boolean;
151 | }
152 | 
153 | export interface CoverageFinding extends AgentFinding {
154 |   agent: 'COV';
155 |   action: 'missing_coverage';
156 | }
