Contents of file bob-kit/skills/sdlc-harness/src/skill/telemetry.ts:

1 | /**
2 |  * telemetry.ts — Suggestion Telemetry (Task 26).
3 |  *
4 |  * Appends one JSON object per accepted, edited, or rejected decision to
5 |  * `sdlc-harness-telemetry.jsonl` in the current working directory.
6 |  *
7 |  * Rules:
8 |  *  - APPEND ONLY — never truncates or overwrites the file.
9 |  *  - No issue content or secrets are written — only agent tag, issue IID,
10 |  *    action label, outcome, and timestamp.
11 |  *  - Skip decisions are NOT logged (they are neutral).
12 |  *  - Provides acceptance-rate summary logic via `computeAcceptanceRate()`.
13 |  *  - The telemetry file itself must be gitignored (see .gitignore).
14 |  */
15 | 
16 | import * as fs from 'fs';
17 | import * as path from 'path';
18 | import * as readline from 'readline';
19 | import type { TelemetryEntry } from '../models';
20 | 
21 | // ---------------------------------------------------------------------------
22 | // File path
23 | // ---------------------------------------------------------------------------
24 | 
25 | /**
26 |  * Resolve the telemetry file path.
27 |  * Defaults to `sdlc-harness-telemetry.jsonl` in the working directory.
28 |  * Override via the SDLC_TELEMETRY_PATH env var for tests.
29 |  */
30 | export function resolveTelemetryPath(): string {
31 |   return (
32 |     process.env['SDLC_TELEMETRY_PATH'] ??
33 |     path.join(process.cwd(), 'sdlc-harness-telemetry.jsonl')
34 |   );
35 | }
36 | 
37 | // ---------------------------------------------------------------------------
38 | // Append
39 | // ---------------------------------------------------------------------------
40 | 
41 | /**
42 |  * Append a single telemetry entry to the JSONL file.
43 |  * Creates the file if it does not exist. Never overwrites existing entries.
44 |  */
45 | export async function appendTelemetry(entry: TelemetryEntry): Promise<void> {
46 |   const filePath = resolveTelemetryPath();
47 |   const line = JSON.stringify(entry) + '\n';
48 |   fs.appendFileSync(filePath, line, { encoding: 'utf8' });
49 | }
50 | 
51 | // ---------------------------------------------------------------------------
52 | // Read
53 | // ---------------------------------------------------------------------------
54 | 
55 | /**
56 |  * Read all telemetry entries from the JSONL file.
57 |  * Returns an empty array if the file does not exist.
58 |  */
59 | export async function readTelemetry(): Promise<TelemetryEntry[]> {
60 |   const filePath = resolveTelemetryPath();
61 | 
62 |   if (!fs.existsSync(filePath)) return [];
63 | 
64 |   const entries: TelemetryEntry[] = [];
65 |   const fileStream = fs.createReadStream(filePath, { encoding: 'utf8' });
66 |   const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });
67 | 
68 |   return new Promise<TelemetryEntry[]>((resolve, reject) => {
69 |     rl.on('line', (line) => {
70 |       const trimmed = line.trim();
71 |       if (trimmed.length === 0) return;
72 |       try {
73 |         entries.push(JSON.parse(trimmed) as TelemetryEntry);
74 |       } catch {
75 |         // Ignore malformed lines — telemetry reads should be resilient
76 |       }
77 |     });
78 |     rl.on('close', () => resolve(entries));
79 |     rl.on('error', reject);
80 |   });
81 | }
82 | 
83 | // ---------------------------------------------------------------------------
84 | // Acceptance-rate summary
85 | // ---------------------------------------------------------------------------
86 | 
87 | export interface AcceptanceRateSummary {
88 |   total: number;
89 |   accepted: number;
90 |   edited: number;
91 |   rejected: number;
92 |   /** accepted / total — or 0 if no entries. */
93 |   acceptanceRate: number;
94 |   /** (accepted + edited) / total — or 0 if no entries. */
95 |   approvalRate: number;
96 | }
97 | 
98 | /**
99 |  * Compute acceptance-rate statistics from a set of telemetry entries.
100 |  * Skipped decisions are not in the log and so are not counted.
101 |  */
102 | export function computeAcceptanceRate(
103 |   entries: TelemetryEntry[]
104 | ): AcceptanceRateSummary {
105 |   const total = entries.length;
106 |   if (total === 0) {
107 |     return { total: 0, accepted: 0, edited: 0, rejected: 0, acceptanceRate: 0, approvalRate: 0 };
108 |   }
109 | 
110 |   const accepted = entries.filter((e) => e.outcome === 'accepted').length;
111 |   const edited   = entries.filter((e) => e.outcome === 'edited').length;
112 |   const rejected = entries.filter((e) => e.outcome === 'rejected').length;
113 | 
114 |   return {
115 |     total,
116 |     accepted,
117 |     edited,
118 |     rejected,
119 |     acceptanceRate: accepted / total,
120 |     approvalRate: (accepted + edited) / total,
121 |   };
122 | }
123 |

Contents of file bob-kit/skills/sdlc-harness/src/agents/state-transition-agent.ts:

1 | /**
2 |  * state-transition-agent.ts — State Transition Agent (Task 23).
3 |  *
4 |  * Correlates an issue's current state with merge-request activity and the
5 |  * project's configured transition rules, then proposes a valid next state.
6 |  *
7 |  * Rules:
8 |  *  - Only proposes a transition allowed by `config.transitionRules`.
9 |  *  - Never proposes the same state the issue is already in.
10 |  *  - Never writes to GitLab — proposals only.
11 |  *  - Returns null when no signal or no valid transition is found.
12 |  *
13 |  * Signal mapping:
14 |  *  - MR state "merged"  → propose "In Review" (work landed, awaiting review)
15 |  *  - MR state "opened"  → propose "In Progress" (active development)
16 |  *  - No linked MRs      → no signal, return null
17 |  *
18 |  * The agent normalises GitLab's "opened" state to "Open" for comparison
19 |  * against the project's configured workflow states.
20 |  */
21 | 
22 | import type { IssueInput, MRInput, ProjectConfig, AgentFinding } from '../models';
23 | 
24 | // ---------------------------------------------------------------------------
25 | // State normalisation
26 | // ---------------------------------------------------------------------------
27 | 
28 | /**
29 |  * Map GitLab API state strings to the canonical configured state names.
30 |  * GitLab uses "opened"/"closed"; the project config may use "Open"/"Done".
31 |  */
32 | function normaliseState(gitlabState: string, configStates: string[]): string {
33 |   const lower = gitlabState.toLowerCase();
34 | 
35 |   // Direct case-insensitive match first
36 |   const direct = configStates.find((s) => s.toLowerCase() === lower);
37 |   if (direct) return direct;
38 | 
39 |   // Common alias map
40 |   if (lower === 'opened') {
41 |     return configStates.find((s) => /^open$/i.test(s)) ?? gitlabState;
42 |   }
43 |   if (lower === 'closed') {
44 |     return configStates.find((s) => /^(done|closed|complete)/i.test(s)) ?? gitlabState;
45 |   }
46 | 
47 |   return gitlabState;
48 | }
49 | 
50 | // ---------------------------------------------------------------------------
51 | // MR → activity signal
52 | // ---------------------------------------------------------------------------
53 | 
54 | type ActivitySignal = 'mr_merged' | 'mr_open' | 'none';
55 | 
56 | /**
57 |  * Derive the strongest activity signal from the provided MR list.
58 |  * "merged" beats "opened" because it represents completed work.
59 |  */
60 | function deriveSignal(mrs: MRInput[]): ActivitySignal {
61 |   if (mrs.some((mr) => mr.state === 'merged')) return 'mr_merged';
62 |   if (mrs.some((mr) => mr.state === 'opened')) return 'mr_open';
63 |   return 'none';
64 | }
65 | 
66 | // ---------------------------------------------------------------------------
67 | // Target state resolution
68 | // ---------------------------------------------------------------------------
69 | 
70 | /** Signal → preferred next state (canonical name as used in config). */
71 | const SIGNAL_TARGET: Record<ActivitySignal, string | null> = {
72 |   mr_merged: 'In Review',
73 |   mr_open: 'In Progress',
74 |   none: null,
75 | };
76 | 
77 | /**
78 |  * BFS reachability: check if `target` state is reachable from `from` state
79 |  * by following the configured transition rules (direct or multi-hop).
80 |  */
81 | function isReachable(from: string, target: string, rules: ProjectConfig['transitionRules']): boolean {
82 |   const visited = new Set<string>();
83 |   const queue = [from];
84 |   while (queue.length > 0) {
85 |     const current = queue.shift()!;
86 |     if (current.toLowerCase() === target.toLowerCase()) return true;
87 |     if (visited.has(current)) continue;
88 |     visited.add(current);
89 |     for (const next of rules[current] ?? []) {
90 |       queue.push(next);
91 |     }
92 |   }
93 |   return false;
94 | }
95 | 
96 | /**
97 |  * Return the next valid state for an issue given a signal, or null if no
98 |  * transition makes sense. Checks direct or transitive reachability.
99 |  */
100 | function resolveNextState(
101 |   currentState: string,
102 |   signal: ActivitySignal,
103 |   config: ProjectConfig
104 | ): string | null {
105 |   const preferredTarget = SIGNAL_TARGET[signal];
106 |   if (!preferredTarget) return null;
107 | 
108 |   // Check if the issue is already in the preferred target state
109 |   if (currentState.toLowerCase() === preferredTarget.toLowerCase()) return null;
110 | 
111 |   // Find the canonical name for the preferred target in the configured states
112 |   const canonicalTarget = config.workflowStates.find(
113 |     (s) => s.toLowerCase() === preferredTarget.toLowerCase()
114 |   );
115 | 
116 |   if (!canonicalTarget) return null;
117 | 
118 |   // Allow the transition if the target is directly OR transitively reachable
119 |   const reachable = isReachable(currentState, canonicalTarget, config.transitionRules);
120 |   if (reachable) return canonicalTarget;
121 | 
122 |   // Not reachable via rules — don't propose a transition
123 |   return null;
124 | }
125 | 
126 | // ---------------------------------------------------------------------------
127 | // Agent entry point
128 | // ---------------------------------------------------------------------------
129 | 
130 | /**
131 |  * Run the state-transition agent for a single issue.
132 |  *
133 |  * @param issue   The issue to evaluate.
134 |  * @param mrs     All MRs linked or related to this issue (caller responsibility).
135 |  * @param config  Project configuration with transition rules.
136 |  * @returns       AgentFinding proposing a state transition, or null.
137 |  */
138 | export async function runStateTransitionAgent(
139 |   issue: IssueInput,
140 |   mrs: MRInput[],
141 |   config: ProjectConfig
142 | ): Promise<AgentFinding | null> {
143 |   const signal = deriveSignal(mrs);
144 |   if (signal === 'none') return null;
145 | 
146 |   const currentNorm = normaliseState(issue.state, config.workflowStates);
147 |   const nextState = resolveNextState(currentNorm, signal, config);
148 | 
149 |   if (!nextState) return null;
150 | 
151 |   const signalDesc =
152 |     signal === 'mr_merged'
153 |       ? 'a linked merge request was merged'
154 |       : 'a linked merge request is open and in progress';
155 | 
156 |   return {
157 |     agent: 'ST',
158 |     issueIid: issue.iid,
159 |     action: 'state_transition',
160 |     suggestedValue: nextState,
161 |     reason:
162 |       `Issue is currently "${currentNorm}" but ${signalDesc}. ` +
163 |       `Transitioning to "${nextState}" reflects the current activity and is ` +
164 |       `a valid move under the configured transition rules.`,
165 |   };
166 | }
167 |

