1 | /**
2 |  * onboard.ts — guided onboarding for the sdlc-harness skill (Task 18).
3 |  *
4 |  * This module is a pure, deterministic function with no side-effects
5 |  * beyond returning validated config. Persistence to `.sdlc-harness.json`
6 |  * is handled by the caller (the SKILL.md conversation flow) so that
7 |  * unit tests can exercise validation without touching the filesystem.
8 |  */
9 | 
10 | import type { ProjectConfig, TransitionRules } from '../models';
11 | 
12 | // ---------------------------------------------------------------------------
13 | // Input / output shapes
14 | // ---------------------------------------------------------------------------
15 | 
16 | export interface OnboardInput {
17 |   projectUrl: string;
18 |   workItemTypes: string[];
19 |   workflowStates: string[];
20 |   transitionRules: TransitionRules;
21 | }
22 | 
23 | export interface OnboardResult {
24 |   ok: boolean;
25 |   config?: ProjectConfig;
26 |   error?: string;
27 | }
28 | 
29 | // ---------------------------------------------------------------------------
30 | // Validation helpers
31 | // ---------------------------------------------------------------------------
32 | 
33 | function validateUrl(url: string): string | null {
34 |   if (!url || url.trim().length === 0) {
35 |     return 'projectUrl is required and must not be empty.';
36 |   }
37 |   // Accept http:// or https:// URLs only
38 |   if (!/^https?:\/\/.+/.test(url.trim())) {
39 |     return 'projectUrl must be a valid http or https URL.';
40 |   }
41 |   return null;
42 | }
43 | 
44 | function validateWorkItemTypes(types: string[]): string | null {
45 |   if (!Array.isArray(types) || types.length === 0) {
46 |     return 'workItemTypes must be a non-empty array of strings.';
47 |   }
48 |   return null;
49 | }
50 | 
51 | function validateWorkflowStates(states: string[]): string | null {
52 |   if (!Array.isArray(states) || states.length === 0) {
53 |     return 'workflowStates must be a non-empty array of state names.';
54 |   }
55 |   return null;
56 | }
57 | 
58 | function validateTransitionRules(
59 |   rules: TransitionRules,
60 |   states: string[]
61 | ): string | null {
62 |   const stateSet = new Set(states);
63 |   for (const [from, targets] of Object.entries(rules)) {
64 |     if (!stateSet.has(from)) {
65 |       return `transitionRules contains unknown source state "${from}". Valid states: ${states.join(', ')}.`;
66 |     }
67 |     for (const to of targets) {
68 |       if (!stateSet.has(to)) {
69 |         return `transitionRules[${from}] references unknown target state "${to}". Valid states: ${states.join(', ')}.`;
70 |       }
71 |     }
72 |   }
73 |   return null;
74 | }
75 | 
76 | // ---------------------------------------------------------------------------
77 | // onboard()
78 | // ---------------------------------------------------------------------------
79 | 
80 | /**
81 |  * Validate onboarding input and return a typed ProjectConfig.
82 |  *
83 |  * This is idempotent: calling it twice with the same valid input returns the
84 |  * same config without error. Callers are responsible for persisting the
85 |  * returned config to `.sdlc-harness.json`.
86 |  */
87 | export async function onboard(input: OnboardInput): Promise<OnboardResult> {
88 |   const urlError = validateUrl(input.projectUrl);
89 |   if (urlError) return { ok: false as const, error: urlError };
90 | 
91 |   const typesError = validateWorkItemTypes(input.workItemTypes);
92 |   if (typesError) return { ok: false as const, error: typesError };
93 | 
94 |   const statesError = validateWorkflowStates(input.workflowStates);
95 |   if (statesError) return { ok: false as const, error: statesError };
96 | 
97 |   const rulesError = validateTransitionRules(
98 |     input.transitionRules,
99 |     input.workflowStates
100 |   );
101 |   if (rulesError) return { ok: false as const, error: rulesError };
102 | 
103 |   const config: ProjectConfig = {
104 |     projectUrl: input.projectUrl.trim(),
105 |     workItemTypes: input.workItemTypes,
106 |     workflowStates: input.workflowStates,
107 |     transitionRules: input.transitionRules,
108 |   };
109 | 
110 |   return { ok: true as const, config };
111 | }
