describe('AC agent', () => {
  test('detects missing AC and returns a Given-When-Then draft', async () => {
    const finding = await runAcAgent(ISSUE_NO_AC, PROJECT_CONFIG);

    expect(finding).not.toBeNull();
    expect(finding!.issueIid).toBe(12);
    expect(finding!.agent).toBe('AC');

    const ac = finding!.suggestedValue as string;
    expect(ac.toLowerCase()).toContain('given');
    expect(ac.toLowerCase()).toContain('when');
    expect(ac.toLowerCase()).toContain('then');
  });

  test('returns null for an issue that already has acceptance criteria', async () => {
    const issueWithAc = {
      ...ISSUE_NO_AC,
      description: ISSUE_NO_AC.description +
        '\n\n**Acceptance Criteria**\nGiven a logged-in user\nWhen they open the dashboard\nThen they see the 5-day forecast widget',
    };

    const finding = await runAcAgent(issueWithAc, PROJECT_CONFIG);
    expect(finding).toBeNull();
  });

  test('returns null for issue with inline Given/When/Then', async () => {
    const issueWithInlineGWT = {
      ...ISSUE_NO_AC,
      description: 'Users need forecast data.\n\nGiven user is on dashboard\nWhen they look at forecast panel\nThen they see 5-day data',
    };
    const finding = await runAcAgent(issueWithInlineGWT, PROJECT_CONFIG);
    expect(finding).toBeNull();
  });

  test('draft references concrete nouns from the title', async () => {
    const finding = await runAcAgent(ISSUE_NO_AC, PROJECT_CONFIG);
    const ac = finding!.suggestedValue.toLowerCase();
    // Should mention "weather" or "forecast" or "widget" from the title
    const mentionsTitle = ac.includes('weather') || ac.includes('forecast') || ac.includes('widget');
    expect(mentionsTitle).toBe(true);
  });

  // P0-2 regression: "Add dark mode toggle to the settings page"
  test('P0-2: title verb is preserved — "Add dark mode toggle" reads as English', async () => {
    const issue = {
      iid: 99,
      title: 'Add dark mode toggle to the settings page',
      description: 'Users want to switch between light and dark themes.',
      labels: ['Story'],
      state: 'opened',
      assignee: null,
    };
    const finding = await runAcAgent(issue, PROJECT_CONFIG);
    expect(finding).not.toBeNull();
    const ac = finding!.suggestedValue;
    // Must contain the full title phrase, not just "dark mode toggle to the settings page"
    expect(ac).toContain('add dark mode toggle to the settings page');
    // Must NOT be "When the user dark mode toggle..." (verb stripped)
    expect(ac).not.toMatch(/when the \w+ dark mode toggle/i);
  });

  // P0-3 regression: no "responds correctly" in AC output
  test('P0-3: draft AC does not contain subjective qualifiers ("correctly", "properly")', async () => {
    const finding = await runAcAgent(ISSUE_NO_AC, PROJECT_CONFIG);
    expect(finding).not.toBeNull();
    const ac = finding!.suggestedValue.toLowerCase();
    expect(ac).not.toContain('correctly');
    expect(ac).not.toContain('properly');
    expect(ac).not.toContain('nicely');
  });

  // P1-8 regression: ordinary prose "Given...when...then" spanning sentences should NOT match
  test('P1-8: ordinary prose with Given/when/then spread across sentence boundaries is not detected as AC', () => {
    const prose = 'Given the deadline is tight, when we ship this, then we should keep scope small.';
    // This is a single-line sentence that contains given/when/then as connective words.
    // The pattern should NOT match because they are not structured GWT.
    // Actually this IS a single line — verify the tightened regex handles it.
    // The new regex uses [^\n]+ so it still matches inline given/when/then.
    // The correct regression for P1-8 is multi-line prose, not single-line.
    const multiLineProse = 'Given the deadline is tight,\nwhen we ship this,\nthen we should keep scope small.';
    expect(hasAcceptanceCriteria(multiLineProse)).toBe(false);
  });
});

