    const snap2 = await readTelemetry();

    // All entries from snap1 must still be present at the start of snap2
    expect(snap2.length).toBe(len1 + 1);
    for (let i = 0; i < snap1.length; i++) {
      expect(snap2[i]).toEqual(snap1[i]);
