    const finding = await runStateTransitionAgent(
      alreadyInReview,
      [MR_MERGED_FOR_ISSUE_5],
      PROJECT_CONFIG,
    );

    expect(finding).toBeNull();
  });

  test('returns null when there is no activity signal', async () => {
