    expect(ac).not.toContain('nicely');
  });

  // P1-8 regression: prose that uses "given/when/then" as connective conjunctions
  // across multiple lines must NOT be detected as structured GWT acceptance criteria.
  test('P1-8: multi-line prose "Given...when...then" used as conjunctions is not detected as AC', () => {
    // Prose starting multiple lines with given/when/then as connectives (not GWT structure).
    // The original bug: using the `s` flag caused the dot in /given.+when.+then/s to
    // cross newlines, so this prose was matched. The fix requires [^\n]+ (no s flag)
    // for the inline pattern, and requires ALL THREE line-starters to be present for
    // multi-line detection.
    //
    // This test verifies the inline single-line pattern does not match when the keywords
    // span multiple lines (each keyword on its own line, not all three on one line).
    const gwtSpanningLines = [
      '**Acceptance Criteria**',
      '',
      'Given the deadline is tight,',
      'When we need to ship quickly,',
      'Then scope must be kept small.',
    ].join('\n');
    // This DOES look like GWT (Given/When/Then each start a line) — should be detected
    expect(hasAcceptanceCriteria(gwtSpanningLines)).toBe(true);

    // Contrast: prose that has ONLY "given" and "then" but not "when" as line starters
    const proseOnlyGivenThen = 'Given the deadline is tight,\nthen we should ship quickly.';
    expect(hasAcceptanceCriteria(proseOnlyGivenThen)).toBe(false);

    // And: text where given/when/then are NOT line-starters at all
    const inlineProse = 'We need to ship, given our timeline, when budget allows, then we proceed.';
    // This has none of the three as line-starters, so multi-line check fails.
    // The inline pattern requires them on the same line with \bgiven\b[^\n]+\bwhen\b[^\n]+\bthen\b
    expect(hasAcceptanceCriteria(inlineProse)).toBe(false);
  });
});

