    'Open': ['In Progress'],
    'In Progress': ['In Review', 'Open'],
    'In Review': ['Done', 'In Progress'],
  },
};

/** Issue with no acceptance criteria */
const ISSUE_NO_AC = {
  iid: 12,
  title: 'Add weather forecast widget',
  description: 'Users should be able to see a 5-day forecast on the dashboard.',
