  // P0-3 regression: no "responds correctly" in AC output
  test('P0-3: draft AC does not contain subjective qualifiers ("correctly", "properly")', async () => {
    const finding = await runAcAgent(ISSUE_NO_AC, PROJECT_CONFIG);
    expect(finding).not.toBeNull();
    const ac = finding!.suggestedValue.toLowerCase();
    expect(ac).not.toContain('correctly');
    expect(ac).not.toContain('properly');
    expect(ac).not.toContain('nicely');
  });

  // P1-8 regression: the original code used /given.+when.+then/is (with `s` flag).
  // The `s` flag makes `.` match newlines, so the pattern crossed line boundaries and
  // falsely detected multi-paragraph prose as structured AC.
  // The fix: use [^\n]+ (no `s` flag) for the inline pattern so keywords must be on
  // the same line; use a 3-keyword line-start check that requires ALL THREE for multiline.
  test('P1-8: the old s-flag false positive — "Given...when...then" on separate lines without all three line-starters is not AC', () => {
    // This is the exact string from the defect report.
    // OLD behaviour: /given.+when.+then/is matched this because s makes . cross newlines.
    // NEW behaviour: inline pattern uses [^\n]+ so it does NOT cross lines; multiline
    // check requires given+when+then all as line starters — only given and then here.
    const oldFalsePositive = 'Given the deadline is tight, when we ship this, then we should keep scope small.';
    // This is actually all one line, so it WILL still match inline — that's expected and fine.
    // The real regression from P1-8 is a multi-paragraph issue description like:
    const multiParaProse = [
      'The feature needs to be built.',
      '',
      'Given current constraints this will be challenging.',
      'We should find time when the sprint allows.',
      'Then we can revisit the architecture then.',
    ].join('\n');
    // Has "given", "when", "then" in prose — but NOT as structured line-starters all three.
    // "given" is a line-starter, "when" and "then" are not (they appear mid-sentence).
    expect(hasAcceptanceCriteria(multiParaProse)).toBe(false);

    // Structured GWT (all three as line starters) SHOULD be detected:
    const structuredGWT = 'Given a user is on the dashboard\nWhen they click the widget\nThen they see the forecast';
    expect(hasAcceptanceCriteria(structuredGWT)).toBe(true);

    // Prose with only two of three keywords as line-starters should NOT be detected:
    const proseOnlyGivenThen = 'Given the deadline is tight,\nthen we should ship quickly.';
    expect(hasAcceptanceCriteria(proseOnlyGivenThen)).toBe(false);
  });
});

