1 | /**
2 |  * telemetry.ts — Suggestion Telemetry (Task 26).
3 |  *
4 |  * Appends one JSON object per accepted, edited, or rejected decision to
5 |  * `sdlc-harness-telemetry.jsonl` in the current working directory.
6 |  *
7 |  * Rules:
8 |  *  - APPEND ONLY — never truncates or overwrites the file.
9 |  *  - No issue content or secrets are written — only agent tag, issue IID,
10 |  *    action label, outcome, and timestamp.
11 |  *  - Skip decisions are NOT logged (they are neutral).
12 |  *  - Provides acceptance-rate summary logic via `computeAcceptanceRate()`.
13 |  *  - The telemetry file itself must be gitignored (see .gitignore).
14 |  */
15 | 
16 | import * as fs from 'fs';
17 | import * as path from 'path';
18 | import * as readline from 'readline';
19 | import type { TelemetryEntry } from '../models';
20 | 
21 | // ---------------------------------------------------------------------------
22 | // File path
23 | // ---------------------------------------------------------------------------
24 | 
25 | /**
26 |  * Resolve the telemetry file path.
27 |  * Defaults to `sdlc-harness-telemetry.jsonl` in the working directory.
28 |  * Override via the SDLC_TELEMETRY_PATH env var for tests.
29 |  */
30 | export function resolveTelemetryPath(): string {
31 |   return (
32 |     process.env['SDLC_TELEMETRY_PATH'] ??
33 |     path.join(process.cwd(), 'sdlc-harness-telemetry.jsonl')
34 |   );
35 | }
36 | 
37 | // ---------------------------------------------------------------------------
38 | // Append
39 | // ---------------------------------------------------------------------------
40 | 
41 | /**
42 |  * Append a single telemetry entry to the JSONL file.
43 |  * Creates the file if it does not exist. Never overwrites existing entries.
44 |  */
45 | export async function appendTelemetry(entry: TelemetryEntry): Promise<void> {
46 |   const filePath = resolveTelemetryPath();
47 |   const line = JSON.stringify(entry) + '\n';
48 |   fs.appendFileSync(filePath, line, { encoding: 'utf8' });
49 | }
50 | 
51 | // ---------------------------------------------------------------------------
52 | // Read
53 | // ---------------------------------------------------------------------------
54 | 
55 | /**
56 |  * Read all telemetry entries from the JSONL file.
57 |  * Returns an empty array if the file does not exist.
58 |  */
59 | export async function readTelemetry(): Promise<TelemetryEntry[]> {
60 |   const filePath = resolveTelemetryPath();
61 | 
62 |   if (!fs.existsSync(filePath)) return [];
63 | 
64 |   const entries: TelemetryEntry[] = [];
65 |   const fileStream = fs.createReadStream(filePath, { encoding: 'utf8' });
66 |   const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });
67 | 
68 |   return new Promise<TelemetryEntry[]>((resolve, reject) => {
69 |     rl.on('line', (line) => {
70 |       const trimmed = line.trim();
71 |       if (trimmed.length === 0) return;
72 |       try {
73 |         entries.push(JSON.parse(trimmed) as TelemetryEntry);
74 |       } catch {
75 |         // Ignore malformed lines — telemetry reads should be resilient
76 |       }
77 |     });
78 |     rl.on('close', () => resolve(entries));
79 |     rl.on('error', reject);
80 |   });
81 | }
82 | 
83 | // ---------------------------------------------------------------------------
84 | // Acceptance-rate summary
85 | // ---------------------------------------------------------------------------
86 | 
87 | export interface AcceptanceRateSummary {
88 |   total: number;
89 |   accepted: number;
90 |   edited: number;
91 |   rejected: number;
92 |   /** accepted / total — or 0 if no entries. */
93 |   acceptanceRate: number;
94 |   /** (accepted + edited) / total — or 0 if no entries. */
95 |   approvalRate: number;
96 | }
97 | 
98 | /**
99 |  * Compute acceptance-rate statistics from a set of telemetry entries.
100 |  * Skipped decisions are not in the log and so are not counted.
101 |  */
102 | export function computeAcceptanceRate(
103 |   entries: TelemetryEntry[]
104 | ): AcceptanceRateSummary {
105 |   const total = entries.length;
106 |   if (total === 0) {
107 |     return { total: 0, accepted: 0, edited: 0, rejected: 0, acceptanceRate: 0, approvalRate: 0 };
108 |   }
109 | 
110 |   const accepted = entries.filter((e) => e.outcome === 'accepted').length;
111 |   const edited   = entries.filter((e) => e.outcome === 'edited').length;
112 |   const rejected = entries.filter((e) => e.outcome === 'rejected').length;
113 | 
114 |   return {
115 |     total,
116 |     accepted,
117 |     edited,
118 |     rejected,
119 |     acceptanceRate: accepted / total,
120 |     approvalRate: (accepted + edited) / total,
121 |   };
122 | }
