    expect(ac).not.toContain('correctly');
    expect(ac).not.toContain('properly');
    expect(ac).not.toContain('nicely');
  });

  // P1-8 regression: the original code used /given.+when.+then/is (with `s` flag).
  // The `s` flag makes `.` match newlines, so the pattern crossed line boundaries and
  // falsely detected multi-paragraph prose as structured AC.
  // The fix: use [^\n]+ (no `s` flag) for the inline pattern so keywords must be on
  // the same line; use a 3-keyword line-start check that requires ALL THREE for multiline.
  test('P1-8: the old s-flag false positive — "Given...when...then" on separate lines without all three line-starters is not AC', () => {
    // The real regression from P1-8: a multi-paragraph issue description where
    // "given/when/then" appear in prose but NOT as all three structured line-starters.
    const multiParaProse = [
      'The feature needs to be built.',
      '',
      'Given current constraints this will be challenging.',
      'We should find time when the sprint allows.',
      'Then we can revisit the architecture then.',
    ].join('\n');
    // Has "given", "when", "then" in prose — but NOT as structured line-starters all three.
    // "given" is a line-starter, "when" and "then" are not (they appear mid-sentence).
    expect(hasAcceptanceCriteria(multiParaProse)).toBe(false);

