import { runAcAgent, hasAcceptanceCriteria } from './src/agents/ac-agent';

const issue = {
  iid: 99,
  title: 'Add dark mode toggle to the settings page',
  description: 'Users want to switch between light and dark themes.',
  labels: ['Story'],
  state: 'opened',
  assignee: null,
