1 | import type { IssueInput, ProjectConfig, AgentFinding, DraftBrief } from '../models';
2 | 
3 | /**
4 |  * Wording that cannot be tested against. Each pattern captures the offending
5 |  * span so the drafter is told exactly what to replace, rather than being handed
6 |  * a vague complaint about the description as a whole.
7 |  *
8 |  * "correctly" and "properly" are deliberately absent: the AC agent's own output
9 |  * used to contain them, and flagging it created a loop where one agent's
10 |  * suggestion tripped the other's detector.
11 |  */
12 | const VAGUE_PATTERNS: Array<{ label: string; re: RegExp }> = [
13 |   { label: 'placeholder', re: /\b(tbd|todo|fixme|placeholder|xxx)\b/i },
14 |   { label: 'non-specific pronoun', re: /\b(the\s+thing|the\s+stuff|something|somehow|some\s+way)\b/i },
15 |   { label: 'vague subject', re: /\b(it\s+(?:doesn'?t|does\s+not|isn'?t|is\s+not)\s+work|fix\s+it)\b/i },
16 |   { label: 'non-testable claim', re: /\b(?:does\s+not|doesn'?t)\s+work\b/i },
17 |   { label: 'vague quantity', re: /\b(various|several\s+things|many\s+things|some\s+issues|a\s+few\s+things)\b/i },
18 | ];
19 | 
20 | /**
21 |  * Signals that an author has already been specific. Two or more of these in a
22 |  * description of reasonable length outweighs a single loose word.
23 |  */
24 | const SPECIFICITY_SIGNALS = [
25 |   /\/[a-z0-9_/-]+/,
26 |   /`[^`]+`/,
27 |   /https?:\/\//,
28 |   /\bapi\b/i,
29 |   /\bcomponent\b/i,
30 |   /\bendpoint\b/i,
31 |   /\bclass\b|\bfunction\b|\bmethod\b/i,
32 | ];
33 | 
34 | const MIN_SPECIFIC_LENGTH = 80;
35 | 
36 | function isConcreteEnough(description: string): boolean {
37 |   if (description.length < MIN_SPECIFIC_LENGTH) return false;
38 |   return SPECIFICITY_SIGNALS.filter((re) => re.test(description)).length >= 2;
39 | }
40 | 
41 | interface Flag {
42 |   label: string;
43 |   phrase: string;
44 | }
45 | 
46 | function findVaguePhrases(text: string): Flag[] {
47 |   const flags: Flag[] = [];
48 |   for (const { label, re } of VAGUE_PATTERNS) {
49 |     const m = text.match(re);
50 |     if (m) flags.push({ label, phrase: m[0] });
51 |   }
52 |   return flags;
53 | }
54 | 
55 | /** Concrete anchors already present in the issue, offered to the drafter as reusable material. */
56 | function anchors(description: string): string[] {
57 |   const found = new Set<string>();
58 |   for (const re of [/`([^`]+)`/g, /\/[a-z0-9_/-]{3,}/g, /\b[A-Z][a-zA-Z]+(?:Error|Exception)\b/g]) {
59 |     for (const m of description.matchAll(re)) found.add(m[1] ?? m[0]);
60 |   }
61 |   return [...found];
62 | }
63 | 
64 | function buildBrief(issue: IssueInput, flags: Flag[]): DraftBrief {
65 |   const desc = issue.description ?? '';
66 |   const reusable = anchors(desc);
67 | 
68 |   const unknowns = flags.map(
69 |     (f) =>
70 |       `"${f.phrase}" (${f.label}) has no concrete replacement in the issue. ` +
71 |       `Ask the author what it refers to instead of choosing a value.`
72 |   );
73 | 
74 |   return {
75 |     task:
76 |       'Rewrite this description so every statement can be verified. Preserve the ' +
77 |       'author\'s intent and keep their voice — this replaces their text, so do not ' +
78 |       'pad it, restructure it into a template, or add sections they did not ask for. ' +
79 |       'Replace each flagged phrase with detail drawn from the issue itself. Where the ' +
80 |       'issue does not supply that detail, leave a direct question to the author in its ' +
81 |       'place rather than inventing a value.',
82 |     context: {
83 |       title: issue.title,
84 |       description: desc,
85 |       flaggedPhrases: flags.map((f) => `${f.phrase} (${f.label})`).join('; '),
86 |       reusableDetail: reusable.join(', '),
87 |     },
88 |     unknowns,
89 |   };
90 | }
91 | 
92 | export async function runAmbiguityAgent(
93 |   issue: IssueInput,
94 |   _config: ProjectConfig
95 | ): Promise<AgentFinding | null> {
96 |   const desc = issue.description ?? '';
97 |   if (isConcreteEnough(desc)) return null;
98 | 
99 |   const flags = findVaguePhrases(`${issue.title} ${desc}`);
100 |   if (flags.length === 0) return null;
101 | 
102 |   const summary = flags.map((f) => `"${f.phrase}"`).join(', ');
103 | 
104 |   return {
105 |     agent: 'AM',
106 |     issueIid: issue.iid,
107 |     action: 'rewrite_desc',
108 |     suggestedValue: `Description not yet rewritten for "${issue.title}".`,
109 |     draft: buildBrief(issue, flags),
110 |     reason: `Vague wording that cannot be tested against: ${summary}.`,
111 |   };
112 | }
