18 | export function hasAcceptanceCriteria(description: string | null): boolean {
19 |   if (!description || !description.trim()) return false;
20 |   return AC_HEADINGS.some((re) => re.test(description)) || hasStructuredGWT(description);
21 | }
22 | 
23 | /** Label vocabulary shared with the work-item-format MCP tool. */
24 | const TYPE_BY_LABEL: Array<[RegExp, string]> = [
25 |   [/\bbug\b|\bdefect\b/i, 'Bug'],
26 |   [/\bepic\b/i, 'Epic'],
27 |   [/\bfeature\b/i, 'Feature'],
28 |   [/\btask\b|\bchore\b/i, 'Task'],
29 | ];
30 | 
31 | function workItemType(labels: string[]): string {
32 |   const joined = labels.join(' ');
33 |   const hit = TYPE_BY_LABEL.find(([re]) => re.test(joined));
34 |   return hit ? hit[1] : 'User Story';
35 | }
36 | 
37 | const ACTOR_BY_TYPE: Record<string, string> = {
38 |   Bug: 'tester',
39 |   Task: 'developer',
40 |   Epic: 'product owner',
41 | };
42 | 
43 | /**
44 |  * Gaps the drafter cannot fill from the issue alone. Each one becomes a
45 |  * question put to the author instead of a guess.
46 |  */
47 | function findGaps(issue: IssueInput): string[] {
48 |   const desc = (issue.description ?? '').trim();
49 |   const gaps: string[] = [];
50 | 
51 |   if (!desc) {
52 |     gaps.push('The issue has no description. Ask the author what "done" looks like before drafting.');
53 |     return gaps;
54 |   }
55 |   if (desc.length < 40) {
56 |     gaps.push('The description is a single line. Ask what the expected outcome is.');
57 |   }
58 |   if (!/\b(when|if|after|once|given)\b/i.test(desc)) {
59 |     gaps.push('No trigger or precondition is stated. Ask what starts the behaviour.');
60 |   }
61 |   if (/\b(error|fail|invalid|reject|timeout)\b/i.test(desc) === false) {
62 |     gaps.push('No failure case is described. Ask what should happen when it goes wrong.');
63 |   }
64 |   return gaps;
65 | }
66 | 
67 | function buildBrief(issue: IssueInput): DraftBrief {
68 |   const type = workItemType(issue.labels);
69 |   const actor = ACTOR_BY_TYPE[type] ?? 'user';
70 | 
71 |   return {
72 |     task:
73 |       `Write 2-4 acceptance criteria for this ${type} in Given-When-Then form. ` +
74 |       `Call work-item-format get-template with type "${type}" and follow the structure it returns. ` +
75 |       `Ground every clause in the issue's own title and description — no filler such as ` +
76 |       `"the system responds correctly" or "the change is visible in the UI", which say nothing ` +
77 |       `and would be true of any issue.`,
78 |     context: {
79 |       title: issue.title,
80 |       description: issue.description ?? '',
81 |       workItemType: type,
82 |       actor,
83 |       labels: issue.labels.join(', '),
84 |     },
85 |     unknowns: findGaps(issue),
86 |   };
87 | }
88 | 
89 | /**
90 |  * Placeholder used only when no drafter is available. It deliberately does not
91 |  * look like finished criteria: applyFinding refuses to write any finding that
92 |  * still carries a draft brief, so this text can never reach an issue.
93 |  */
94 | function undraftedPlaceholder(issue: IssueInput): string {
95 |   return `Acceptance criteria not yet drafted for "${issue.title}".`;
96 | }
97 | 
98 | export async function runAcAgent(
99 |   issue: IssueInput,
100 |   _config: ProjectConfig
101 | ): Promise<AgentFinding | null> {
102 |   if (hasAcceptanceCriteria(issue.description)) return null;
103 | 
104 |   return {
105 |     agent: 'AC',
106 |     issueIid: issue.iid,
107 |     action: 'draft_ac',
108 |     suggestedValue: undraftedPlaceholder(issue),
109 |     draft: buildBrief(issue),
110 |     reason: 'No acceptance criteria found in the description.',
111 |   };
112 | }
